-- UUID identifiers are generated by JPA (GenerationType.UUID).
-- No backfill or seed data is included.

create table locker_zone
(
    id                     uuid         not null primary key,
    organization_id        bigint       not null,
    name                   varchar(100) not null,
    sort_order             integer      not null,
    row_count              integer      not null,
    column_count           integer      not null,
    max_locker_count       integer      not null,
    available_locker_count integer      not null,
    version                bigint,
    layout_revision        bigint       not null,
    created_at             timestamp(6) not null,
    updated_at             timestamp(6) not null,
    constraint fk_locker_zone_organization
        foreign key (organization_id) references organization (organization_id),
    constraint uk_locker_zone_name
        unique (organization_id, name),
    constraint uk_locker_zone_sort_order
        unique (organization_id, sort_order),
    constraint ck_locker_zone_row_count
        check (row_count between 1 and 500),
    constraint ck_locker_zone_column_count
        check (column_count between 1 and 500)
);

create table locker
(
    id                uuid         not null primary key,
    zone_id           uuid         not null,
    label             varchar(50)  not null,
    row_index         integer      not null,
    column_index      integer      not null,
    row_span          integer      not null,
    column_span       integer      not null,
    enable_status     varchar(20)  not null,
    operation_status  varchar(20)  not null,
    version           bigint,
    layout_revision   bigint       not null,
    created_at        timestamp(6) not null,
    updated_at        timestamp(6) not null,
    constraint fk_locker_zone
        foreign key (zone_id) references locker_zone (id),
    constraint uk_locker_label
        unique (zone_id, layout_revision, label),
    constraint uk_locker_index
        unique (zone_id, layout_revision, row_index, column_index),
    constraint ck_locker_row_index
        check (row_index >= 0),
    constraint ck_locker_column_index
        check (column_index >= 0),
    constraint ck_locker_enable_status
        check (enable_status in ('ENABLED', 'DISABLED')),
    constraint ck_locker_operation_status
        check (operation_status in ('AVAILABLE', 'PENDING', 'RENTED', 'UNAVAILABLE'))
);

create table locker_policy
(
    id                  uuid         not null primary key,
    organization_id     bigint       not null,
    rental_days         integer      not null,
    max_extension_count integer      not null,
    extension_days      integer      not null,
    terms               text         not null,
    terms_version       bigint       not null,
    version             bigint,
    created_at          timestamp(6) not null,
    updated_at          timestamp(6) not null,
    constraint fk_locker_policy_organization
        foreign key (organization_id) references organization (organization_id),
    constraint uk_locker_policy_organization
        unique (organization_id),
    constraint ck_locker_policy_rental_days
        check (rental_days > 0),
    constraint ck_locker_policy_max_extension_count
        check (max_extension_count >= 0),
    constraint ck_locker_policy_extension_days
        check (extension_days > 0)
);

-- LockerBorrowerField does not extend BaseTimeEntity.
create table locker_borrower_field
(
    id         bigint generated by default as identity primary key,
    policy_id  uuid         not null,
    field_key  varchar(80)  not null,
    label      varchar(100) not null,
    required   boolean      not null,
    sort_order integer      not null,
    constraint fk_locker_borrower_field_policy
        foreign key (policy_id) references locker_policy (id)
);

create index idx_locker_borrower_field_policy
    on locker_borrower_field (policy_id);

create table locker_rental
(
    id                           uuid         not null primary key,
    public_id                    varchar(64)  not null,
    organization_id              bigint       not null,
    locker_id                    uuid,
    status                       varchar(20)  not null,
    borrower_name                varchar(255) not null,
    borrower_phone               varchar(255) not null,
    borrower_email               varchar(255),
    borrower_additional_info     jsonb,
    requested_at                 timestamp(6) not null,
    approved_at                  timestamp(6),
    approved_by                  varchar(255),
    rejected_at                  timestamp(6),
    rejected_by                  varchar(255),
    reject_reason                varchar(255),
    start_date                   date,
    due_date                     date,
    returned_at                  timestamp(6),
    returned_by                  varchar(255),
    extension_count              integer      not null,
    rental_days                  integer      not null,
    max_extension_count          integer      not null,
    extension_days               integer      not null,
    terms_version                bigint       not null,
    terms_agreed_at              timestamp(6) not null,
    zone_name_snapshot           varchar(255) not null,
    locker_label_snapshot        varchar(255) not null,
    locker_row_index_snapshot    integer      not null,
    locker_column_index_snapshot integer      not null,
    created_at                   timestamp(6) not null,
    updated_at                   timestamp(6) not null,
    constraint fk_locker_rental_organization
        foreign key (organization_id) references organization (organization_id),
    constraint fk_locker_rental_locker
        foreign key (locker_id) references locker (id),
    constraint locker_rental_public_id
        unique (public_id),
    constraint ck_locker_rental_status
        check (status in ('REQUESTED', 'RENTED', 'REJECTED', 'RETURNED')),
    constraint ck_locker_rental_rental_days
        check (rental_days > 0),
    constraint ck_locker_rental_max_extension_count
        check (max_extension_count >= 0),
    constraint ck_locker_rental_extension_days
        check (extension_days > 0),
    constraint ck_locker_rental_row_snapshot
        check (locker_row_index_snapshot >= 0),
    constraint ck_locker_rental_column_snapshot
        check (locker_column_index_snapshot >= 0)
);

create index idx_locker_rental_organization
    on locker_rental (organization_id);

create index idx_locker_rental_locker_status
    on locker_rental (locker_id, status);

create table locker_rental_extension
(
    id                uuid         not null primary key,
    rental_id         uuid         not null,
    status            varchar(20)  not null,
    requested_at      timestamp(6) not null,
    approved_at       timestamp(6),
    approved_by       varchar(255),
    rejected_at       timestamp(6),
    rejected_by       varchar(255),
    reject_reason     varchar(255),
    previous_due_date date         not null,
    new_due_date      date         not null,
    sequence          bigint       not null,
    created_at        timestamp(6) not null,
    updated_at        timestamp(6) not null,
    constraint fk_locker_rental_extension_rental
        foreign key (rental_id) references locker_rental (id),
    constraint uk_rental_extension_sequence
        unique (rental_id, sequence),
    constraint ck_locker_rental_extension_status
        check (status in ('REQUESTED', 'APPROVED', 'REJECTED')),
    constraint ck_locker_rental_extension_due_dates
        check (new_due_date > previous_due_date)
);
